private String addRequiredQuotesAndParameters(String query, Object[] parameters) {
    StringBuilder result = new StringBuilder();
    int paramIndex = 0;

    for (int i = 0; i < query.length(); i++) {
        char currentChar = query.charAt(i);

        if (currentChar == '\'') {
            result.append(currentChar); // Append the single quote
            i++; // Skip the single quote
            while (i < query.length() && query.charAt(i) != '\'') {
                result.append(query.charAt(i)); // Append characters within the string
                i++;
            }
            if (i < query.length()) {
                result.append('\''); // Append the closing single quote
            }
        } else if (currentChar == '$') {
            if (i + 4 < query.length() && query.substring(i, i + 4).equals("$oid")) {
                result.append(parameters[paramIndex]); // Append the parameter value
                paramIndex++;
                i += 3; // Skip the remaining characters of the $oid token
            } else {
                result.append(currentChar); // Append the dollar sign
            }
        } else {
            result.append(currentChar); // Append other characters
        }
    }

    if (paramIndex < parameters.length) {
        throw new IllegalArgumentException("Not enough parameters passed to query: " + query);
    }

    return result.toString();
}

